                i += 1
            elif ch == '\\' and i + 1 < n and line[i + 1] in '"\\':
                cur += line[i + 1]
                i += 2
            else:
                cur += ch
                i += 1
        else:
            if ch == "'":
                state = "'"
                in_word = True
                i += 1
            elif ch == '"':
                state = '"'
                in_word = True
                i += 1
            elif ch == '\\':
                if i + 1 < n:
                    cur += line[i + 1]
                    i += 2
                else:
                    cur += ch  # trailing backslash is kept as a character
                    i += 1
                in_word = True
